                if (nr, nc) in five_cells and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    q.append((nr, nc))
        comps.append(comp)
    comp = max(comps, key=len)
    S = set(comp)

    # Graph neighbors among 5-cells.
    nbrs = {}
    for r, c in S:
        ns = []
        for dr, dc in dirs:
            p = (r + dr, c + dc)
            if p in S:
                ns.append(p)
        nbrs[(r, c)] = ns

    # Critical cells: endpoints, junctions, and corners.
    critical = set()
    for cell, ns in nbrs.items():
        d = len(ns)
        if d != 2:
            critical.add(cell)
        else:
