            dr1, dc1 = r1 - cell[0], c1 - cell[1]
            dr2, dc2 = r2 - cell[0], c2 - cell[1]
            # Straight line if opposite directions.
            if not (dr1 == -dr2 and dc1 == -dc2):
                critical.add(cell)

    if not critical:
        # Degenerate straight line / loop.
        rows = sorted({r for r, _ in S})
        cols = sorted({c for _, c in S})
        out = [[0 for _ in range(max(1, len(cols)))] for _ in range(max(1, len(rows)))]
        if len(rows) == 1:
            for j in range(len(cols)):
                out[0][j] = 2
        elif len(cols) == 1:
            for i in range(len(rows)):
                out[i][0] = 2
        else:
            for i in range(min(len(rows), len(cols))):
                out[i][i] = 2
        return out

